import { createDemo, verifyBundle, repositories, canonical, hashObject } from './ledger.mjs';
import { buildLineage, eventRoute, parseRoute } from './lineage.mjs';
const $=s=>document.querySelector(s);
const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const short=(s,n=12)=>String(s??'').slice(0,n)+'…';
const names={admin:'Super administrator',AAA:'AAA',BBB:'BBB',CCC:'CCC',viewer:'Public visitor'};
const labels={'registry.initialized':'Governance rules published','maintainer.invited':'Maintainer invitation sent','admin_pick.changed':'Admin pick set','recommendation.changed':'Team recommendation changed','proposal.created':'Team change proposed','proposal.voted':'Team vote recorded','maintainer.accepted':'Maintainer handoff completed'};
const category=action=>action.startsWith('maintainer')||action.startsWith('proposal')?'team':action.includes('pick')||action.includes('recommendation')?'recommendation':'policy';
let demo,selected=0,tab='log',actor='AAA',filter='all',sample='original',verification=null,busy=false,toastTimer,unavailable=false;
function role(id=actor){if(id==='admin')return 'Super administrator';if(demo.state.maintainers.includes(id))return 'STAR maintainer';return id==='viewer'?'Public read-only visitor':'No STAR management access';}
function avatar(id){return `<span class="avatar ${id==='admin'?'admin':''}">${escape(id==='admin'?'AD':id==='viewer'?'V':id)}</span>`;}
const shield=`<svg class="shield" width="25" height="29" viewBox="0 0 25 29" fill="none" aria-hidden="true"><path d="M12.5 2 23 6v8c0 7-10.5 13-10.5 13S2 21 2 14V6l10.5-4Z" stroke="currentColor" stroke-width="1.6"/><path d="m7.5 14 3 3 7-7" stroke="currentColor" stroke-width="1.6"/></svg>`;
function title(e){const p=e.body.payload;
  if(e.body.action==='maintainer.invited')return `Invite ${p.candidate} as a STAR maintainer`;
  if(e.body.action==='recommendation.changed')return `${repositories[p.repository].name} selected as a ${p.targetType==='version'?'version':'repository'} recommendation`;
  if(e.body.action==='admin_pick.changed')return `${repositories[p.repository].name} selected as the admin pick`;
  if(e.body.action==='proposal.created')return `${names[e.body.actor]} proposes ${p.kind==='transfer'?'a maintainer handoff to':'adding'} ${p.candidate}`;
  if(e.body.action==='proposal.voted')return `${names[e.body.actor]} approves the team change proposal`;
  if(e.body.action==='maintainer.accepted')return `${e.body.actor} accepts the invitation; the team change takes effect`;
  return 'Publish STAR governance rules 1.0';
}
function pretty(value){
  if(value===null)return 'Not set';if(Array.isArray(value))return value.length?value.join(', '):'No maintainers yet';
  if(typeof value==='string')return repositories[value]?.name??value;
  if(value?.repository){const repo=repositories[value.repository];return `${repo.name} · ${value.targetType==='version'?'Pinned commit '+short(value.commit,8):'Recommended repository (future commits are not automatically endorsed)'}`;}
  if(value?.votes)return `${value.kind==='transfer'?'Handoff to':'Add'} ${value.candidate} · ${value.votes.length}/${value.required} votes · ${statusLabel(value.status)}`;
  return canonical(value);
}
function statusLabel(status){return {voting:'Awaiting team votes',awaiting_acceptance:'Awaiting candidate acceptance',effective:'Effective',superseded:'Proposal superseded'}[status]??status;}
function toast(message,error=false){const el=$('#toast');clearTimeout(toastTimer);el.textContent=message;el.className=error?'error':'';el.hidden=false;toastTimer=setTimeout(()=>{el.hidden=true;},5000);}
function checkpointStrip(){const cp=demo.checkpoint.body;return `<div class="checkpoint-strip"><div class="checkpoint-title">${shield}<div><strong>Published checkpoint #${cp.treeSize} signed</strong><p>Original records and proofs retained for each change · Demo log in this browser</p></div></div><div class="checkpoint-meta"><span class="tag green">${cp.treeSize} public records</span><p>Simulated witnesses 2 / 2</p><code title="${cp.rootHash}">${short(cp.rootHash,16)}</code></div></div>`;}
function stateStrip(){const state=demo.state;$('#current-state').innerHTML=`<div><span class="state-label">Current maintainers</span><span class="people">${state.maintainers.map(avatar).join('')}</span></div><div><span class="state-label">Admin pick</span><strong>${escape(repositories[state.adminPick]?.name??'Not set')}</strong></div><div><span class="state-label">Team recommendation</span><strong>${escape(repositories[state.recommendation?.repository]?.name??'Not set')}</strong> <span class="tag">${state.recommendation?.targetType==='version'?'Pinned commit':'Repository'}</span></div>`;
  const count=Object.values(state.proposals).filter(p=>['voting','awaiting_acceptance'].includes(p.status)).length;$('#pending-count').textContent=count?String(count):'';
  for(const option of $('#actor').options){const id=option.value;option.textContent=id==='admin'?'Super administrator':id==='viewer'?'Public visitor':`${id} · ${state.maintainers.includes(id)?'STAR maintainer':'Pending / former member'}`;}
  $('#actor').value=actor;
}
function inspector(){const e=demo.events[selected],b=e.body;return `<aside class="inspector" aria-label="Selected event details"><div class="inspector-head"><h2>Event details</h2><span class="tag green">Published · Demo</span></div><div class="inspector-body"><div class="detail-label">Event #${String(b.sequence).padStart(3,'0')} · ${escape(labels[b.action])}</div><h3 class="inspector-title">${escape(title(e))}</h3><div class="actor-row">${avatar(b.actor)}<div><strong>${escape(names[b.actor])}</strong><p>${b.actor==='admin'?'Site-wide governance action':'Action within STAR'} · ${new Date(b.recordedAt).toLocaleTimeString('en-US',{hour:'2-digit',minute:'2-digit'})}</p></div></div><div class="detail-label">What changed</div><div class="delta"><div><small>Before</small><p>${escape(pretty(b.change.before))}</p></div><div><small>After</small><p>${escape(pretty(b.change.after))}</p></div></div><div class="detail-label">Public reason</div><p class="reason">${escape(b.reason)}</p><dl class="detail-metadata"><div><dt>Scope</dt><dd>STAR / cp_star</dd></div><div><dt>Policy version</dt><dd>${escape(b.policyVersion)}</dd></div><div><dt>Event hash</dt><dd><code>${short(e.hash,24)}</code></dd></div><div><dt>Previous hash</dt><dd><code>${short(b.previousEventHash,24)}</code></dd></div></dl><div class="inspector-actions"><button class="secondary" data-action="show-lineage">View governance lineage</button><button class="secondary" data-action="copy-link">Copy session link</button><button class="primary" data-action="verify-selected">Verify this record</button><button class="secondary" data-action="download">Download record and proof</button></div><p class="muted session-note">This link identifies a record in this demo session only. Other sessions and page reloads have different logs, so this is not a permanent public link.</p><details class="raw-data"><summary>View complete event and signature</summary><pre>${escape(JSON.stringify(e,null,2))}</pre></details></div></aside>`;}
function logView(){const events=demo.events.map((event,index)=>({event,index})).filter(({event})=>filter==='all'||category(event.body.action)===filter).reverse();return checkpointStrip()+`<div class="section-line"><div><h2>Public change log</h2><p>The production log is intended for public community access. This browser demo records corrections as new events.</p></div><div class="filters"><label class="sr-only" for="event-filter" hidden>Filter events</label><select id="event-filter" aria-label="Filter events"><option value="all">All events</option><option value="team">Members and proposals</option><option value="recommendation">Recommendations and picks</option><option value="policy">Governance rules</option></select></div></div><div class="workspace"><div><ol class="event-list">${events.map(({event:e,index})=>`<li><button class="event-row" data-event="${index}" aria-pressed="${index===selected}"><span class="event-number">${String(e.body.sequence).padStart(3,'0')}</span><div><h3>${escape(title(e))}</h3><p><span class="event-type">${escape(names[e.body.actor])}</span> · ${escape(labels[e.body.action])}</p><div class="row-bottom"><span>STAR <span aria-hidden="true">/</span> <time datetime="${e.body.recordedAt}">${new Date(e.body.recordedAt).toLocaleTimeString('en-US',{hour:'2-digit',minute:'2-digit'})}</time></span><code>${short(e.hash,16)}</code></div></div></button></li>`).join('')}</ol><p class="log-footnote">Only recorded demo events appear here. In production, denied requests go to a restricted security log and are not recorded as successful changes.</p></div>${inspector()}</div>`;}
function teamView(){const state=demo.state;const canManage=actor==='admin'||state.maintainers.includes(actor);return checkpointStrip()+`<div class="two-column"><section class="panel"><div class="panel-title"><h2>STAR maintainers</h2><button class="secondary" data-action="open-invite">Invite / handoff</button></div><p>Access is assigned to an account for a specific tool. Public attribution, a GitHub username, or code contributions do not automatically grant management access.</p>${state.maintainers.map(id=>`<div class="member-row"><div class="member-identity">${avatar(id)}<div><strong>${id}</strong><p>STAR maintainer · Responsibilities accepted</p></div></div><span class="tag green">Access active</span></div>`).join('')}<div class="scope"><strong>Current demo account: ${escape(names[actor])}</strong><p>${escape(role())} · ${canManage?'Can manage STAR':'Read-only; can accept an invitation addressed to this account'}</p></div><button class="secondary" data-action="cross-tool">Try changing the BWA recommendation</button><p class="muted" style="margin-top:12px">Use this action to check tool scope isolation. A denied request does not append a successful event.</p></section><section class="panel"><h2>Permission boundaries</h2><table class="permissions"><thead><tr><th>Capability</th><th>Super administrator</th><th>Maintainer</th></tr></thead><tbody><tr><td>Edit tool details</td><td class="yes">Site-wide</td><td class="yes">Own tool</td></tr><tr><td>Set team recommendation</td><td class="yes">Yes</td><td class="yes">Own tool</td></tr><tr><td>Set admin pick</td><td class="yes">Yes</td><td class="no">No</td></tr><tr><td>Appoint maintainers directly</td><td class="yes">Recorded invitation</td><td>Proposal vote</td></tr><tr><td>Change access for other tools</td><td class="yes">Yes</td><td class="no">No</td></tr><tr><td>Delete history without a trace</td><td class="no">No</td><td class="no">No</td></tr></tbody></table><p class="muted">Switching demo accounts illustrates the rules. Production authentication and permission checks must run on the backend.</p></section></div>`;}
function proposalsView(){const state=demo.state,proposals=Object.values(state.proposals).filter(p=>p.kind!=='admin_add'||p.status!=='effective').reverse();return `<div class="two-column"><section><div class="section-line"><div><h2>Team change proposals</h2><p>Vote first, then obtain candidate acceptance, then publish and activate the change.</p></div><button class="primary" data-action="open-invite">Create proposal</button></div>${proposals.length?proposals.map(p=>`<article class="proposal-card"><div class="proposal-header"><span class="tag ${p.status==='effective'?'green':p.status==='superseded'?'gray':'amber'}">${statusLabel(p.status)}</span><code class="hash-inline">${p.id}</code></div><h3>${p.kind==='transfer'?`${p.proposer} hands off maintenance to ${p.candidate}`:`Add ${p.candidate} as a STAR maintainer`}</h3><p>Proposer ${p.proposer} · Eligible voters ${p.members.join(', ')} · ${p.required} votes required</p><div class="vote-track"><span style="width:${Math.min(100,p.votes.length/p.required*100)}%"></span></div><p>${p.votes.length} / ${p.required} approvals · Approved by: ${p.votes.join(', ')}</p><div class="proposal-actions">${p.status==='voting'?`<button class="primary" data-vote="${p.id}" ${!p.members.includes(actor)||p.votes.includes(actor)?'disabled':''}>Approve proposal</button><p>${p.votes.includes(actor)?'Your vote is recorded publicly.':p.members.includes(actor)?'Your vote will be appended to the public log.':'This account is not in the eligible voter snapshot.'}</p>`:p.status==='awaiting_acceptance'?`<button class="primary" data-accept="${p.id}" ${actor!==p.candidate?'disabled':''}>Accept responsibilities</button><p>Switch to ${p.candidate} to accept. Management access starts after acceptance.</p>`:`<span class="tag ${p.status==='effective'?'green':'gray'}">${p.status==='effective'?'Team access updated':'Previous votes are superseded and cannot reactivate'}</span><p>The original proposal, votes, and acceptance remain in the log.</p>`}</div></article>`).join(''):`<div class="empty"><h3>No team change proposals yet</h3><p style="margin-top:10px">Try creating a proposal for AAA to hand off maintenance to CCC.</p></div>`}</section><aside class="panel"><h2>Try a complete handoff</h2><div class="scenario"><div><strong>1. AAA proposes a handoff</strong><p>Choose “Hand off my responsibilities” and select CCC. The proposal explicitly records an approval vote from AAA.</p></div><div><strong>2. BBB approves</strong><p>Switch to BBB to vote. A two-person team requires both votes.</p></div><div><strong>3. CCC accepts</strong><p>After the threshold is met, switch to CCC and accept the invitation. The team then becomes BBB and CCC.</p></div><div><strong>4. AAA tries another change</strong><p>Switch back to AAA and try changing the recommendation. Access is denied; the departure record remains publicly visible.</p></div></div><p class="muted" style="margin-top:20px">A sole maintainer can nominate a successor; the handoff completes after acceptance. This demo illustrates a two-person team.</p></aside></div>`;}
function verificationView(){const e=demo.events[selected];return `<div class="verification-heading"><div><h2>Verify public records</h2><p>Recompute verification using the public keys pinned for this demo session. Editing a copy does not affect the original public log.</p></div><button class="secondary" data-action="download">Download evidence</button></div><div class="verification-layout"><section class="panel"><h3>Choose a record and test</h3><select class="verify-event-select" id="verify-event" aria-label="Choose a record to verify">${demo.events.map((event,index)=>`<option value="${index}" ${selected===index?'selected':''}>#${event.body.sequence} ${escape(title(event))}</option>`).join('')}</select><div class="sample-controls"><button class="secondary" data-sample="original" aria-pressed="${sample==='original'}">Original record</button><button class="secondary" data-sample="tampered" aria-pressed="${sample==='tampered'}">Tamper with a copy</button><button class="secondary" data-sample="truncated" aria-pressed="${sample==='truncated'}">Remove the final record</button></div><div class="detail-label">${sample==='original'?'Original content, signatures, and published checkpoint retained':sample==='tampered'?'The public reason in the copy is rewritten; the original hash and checkpoint are unchanged':'The copy lacks its final record; the signed checkpoint still declares the complete tree size'}</div><pre class="hash-block">${escape(JSON.stringify({...e.body,reason:sample==='tampered'?'Secretly rewritten reason: grant access to Mallory':e.body.reason},null,2))}</pre><button class="${sample==='original'?'primary':'danger'}" data-action="run-verify" style="width:100%;margin-top:18px">${busy?'Verifying…':sample==='original'?'Verify original record':'Check copy for changes'}</button><div class="verify-scope"><strong>Verification scope</strong><p>SHA-256, action signatures, permission replay, Merkle inclusion proofs, checkpoint signatures, and full-history append checks all run. Each witness has a separate demo key, but both are controlled by this browser and do not represent independent witnesses.</p></div></section><section class="panel"><h3>Verification results</h3>${verification?`<div class="verify-status ${verification.ok?'pass':'fail'}"><strong>${verification.ok?'Original record passed demo verification':'Evidence inconsistency detected'}</strong><p style="color:inherit;margin-top:5px">${verification.ok?'Verification passed under the demo trust roots only.':'The copy does not match the originally signed history.'}</p></div><ol class="check-list">${verification.checks.map(c=>`<li><span class="check-symbol ${c.ok?'':'fail'}">${c.ok?'✓':'×'}</span><div><h3>${escape(c.name)}</h3><p>${escape(c.detail)}</p></div></li>`).join('')}</ol>`:`<div class="verify-status">No verification yet. Choose the original record or a modified copy, then run the check.</div><div class="proof-tree" aria-hidden="true"><div class="tree-item">Event content<br>Hash</div><div class="tree-join"></div><div class="tree-item">Merkle<br>Inclusion proof</div><div class="tree-join"></div><div class="tree-item">Signed<br>checkpoint</div></div><p class="muted">Hash changes can be detected. Trust still requires an explicit choice of keys and checkpoint.</p>`}<div class="witnesses"><div class="witness"><span>Witness A</span><span class="tag gray">Browser simulation</span></div><div class="witness"><span>Witness B</span><span class="tag gray">Browser simulation</span></div></div><button class="text-button" data-action="download-trust">Download demo trust roots</button><p class="muted">Production verification must pin public keys through an independent trusted channel. Keys bundled with the evidence cannot establish identity trust on their own.</p></section></div>`;}
const edgeNames={authority:'Authority source',policy:'Applicable policy',proposal:'Proposal / invitation',vote:'Approval vote'};
function lineageView(){
  const graph=buildLineage(demo.events,demo.events[selected].hash),e=graph.selected,cp=demo.checkpoint.body;
  const selectedRepository=graph.target?.repository;
  const repo=selectedRepository&&repositories[selectedRepository];
  const related=repo?demo.events.map((event,index)=>({event,index})).filter(v=>v.event.body.toolId===e.body.toolId&&v.event.body.payload.repository===selectedRepository):[];
  const recommendation=demo.events.findLastIndex(v=>v.body.action==='recommendation.changed');
  return `<div class="section-line"><div><h2>What authorized this change?</h2><p>Trace the authority and approvals in effect when the action occurred. Dependencies come from event content; verify their authenticity separately.</p></div><label class="lineage-select-label">Trace event<select id="lineage-event" aria-label="Choose an event to trace">${demo.events.map((v,i)=>`<option value="${i}" ${i===selected?'selected':''}>#${v.body.sequence} ${escape(title(v))}</option>`).join('')}</select></label></div>
  <div class="lineage-legend"><span>Governance evidence: authority / policy / proposal / votes</span><span>Previous hash: global log order; see the evidence below</span></div>
  <div class="workspace lineage-workspace"><div><section class="lineage-graph" aria-label="Governance dependencies"><div class="panel-title"><h3>Governance lineage</h3><span class="tag ${graph.missing.length?'amber':'gray'}">${graph.missing.length?'Evidence missing':'Dependencies expanded'}</span></div>
    ${graph.missing.length?`<div class="lineage-warning" role="status">${graph.missing.map(m=>`<p>${escape(m.detail)}</p>`).join('')}</div>`:''}
    <ol class="lineage-nodes">${graph.nodes.map(n=>{if(!n.event)return `<li class="lineage-node trust-node"><span class="lineage-dot" aria-hidden="true"></span><strong>Demo administrator trust root</strong><p>The initial admin identity is preset for this demo. The log does not independently prove that identity.</p></li>`;
    const event=n.event,index=demo.events.findIndex(v=>v.hash===event.hash),incoming=graph.edges.filter(v=>v.to===n.id);
    return `<li class="lineage-node ${n.id===e.hash?'selected-node':''}"><span class="lineage-dot" aria-hidden="true"></span><button class="lineage-node-title" data-lineage="${index}" aria-pressed="${n.id===e.hash}"><span class="detail-label">Event #${event.body.sequence} · ${escape(names[event.body.actor])}</span><strong>${escape(title(event))}</strong></button><p>${escape(event.body.reason)}</p><div class="dependency-links">${incoming.map(v=>{const parent=graph.nodes.find(n=>n.id===v.from);return parent?.event?`<button class="dependency-link" data-lineage="${demo.events.findIndex(e=>e.hash===v.from)}">${edgeNames[v.type]} #${parent.event.body.sequence}</button>`:`<span class="tag gray">Demo administrator authority</span>`;}).join('')}</div></li>`;}).join('')}</ol>
    <p class="muted">This view expands evidence relevant to this action. Appearing in the graph does not mean a record has passed verification; use the signature and evidence checks in the detail panel.</p></section>
    <section class="panel repository-context"><div class="panel-title"><h3>Repository and version</h3><span class="tag gray">Code history tracked separately</span></div>${repo?`<h4>${escape(repo.name)}</h4><a href="${escape(repo.url)}" target="_blank" rel="noopener noreferrer">${escape(repo.url.replace('https://github.com/',''))}</a><p>${graph.target.targetType==='version'?'This recommendation is bound to the specific commit in the signed record.':'This action targets the whole repository without pinning a commit. Future commits do not automatically inherit version endorsement.'}</p>${graph.target.commit&&/^[a-f0-9]{40}$/.test(graph.target.commit)?`<a class="commit-link" href="${repo.url}/commit/${graph.target.commit}" target="_blank" rel="noopener noreferrer">View pinned commit <code>${short(graph.target.commit,12)}</code></a>`:''}<p><a href="${repo.url}/commits" target="_blank" rel="noopener noreferrer">View code history in the source repository</a></p><p class="muted">This demo does not import a commit DAG or infer unverified ancestry between STAR and NuSTAR.</p><div class="detail-label">Governance records for this repository</div><ul class="repository-events">${related.map(v=>`<li><button class="text-button" data-lineage="${v.index}">#${v.event.body.sequence} ${escape(title(v.event))}</button></li>`).join('')}</ul>`:`<p>This team or policy event is not bound to a code version.</p>${recommendation>=0?`<button class="text-button" data-lineage="${recommendation}">Trace the latest recommendation</button>`:''}`}</section>
    <section class="panel anchor-panel"><div class="panel-title"><h3>Where are records stored?</h3><span class="tag amber">No public blockchain connected</span></div><dl class="detail-metadata"><div><dt>Complete events and signatures</dt><dd>Browser memory · Resets on reload</dd></div><div><dt>Current checkpoint</dt><dd>#${cp.treeSize} · Demo signatures and simulated witnesses</dd></div><div><dt>Merkle Root</dt><dd><code class="full-hash">${cp.rootHash}</code></dd></div><div><dt>On-chain transaction</dt><dd>No real transaction or block explorer link</dd></div></dl><p>In production, community members should be able to view governance records, original content, and proofs without signing in. If blockchain anchoring is enabled, each event can link to the transaction for its batch.</p><p class="muted">This demo site remains private. All signatures and witnesses are generated by the same browser and do not represent real identities or independent witnesses.</p></section>
  </div><div>${inspector()}<section class="panel hash-predecessor"><h3>Previous record in the hash chain</h3><p>This shows log ordering. It does not establish authority for the current action.</p>${selected>0&&demo.events[selected-1].hash===e.body.previousEventHash?`<button class="text-button" data-history="${selected-1}">View previous event #${demo.events[selected-1].body.sequence}</button>`:`<p class="muted">This is the first log record; there is no previous event.</p>`}<code class="full-hash">${e.body.previousEventHash}</code></section></div></div>`;
}
function render(){stateStrip();document.querySelector('.heading-actions [data-action="download"]').disabled=unavailable;for(const button of document.querySelectorAll('[data-tab]'))button.setAttribute('aria-selected',String(button.dataset.tab===tab));$('#app').setAttribute('aria-labelledby','tab-'+tab);$('#app').innerHTML=unavailable?`<section class="panel unavailable" role="status"><h2>Record unavailable in this demo session</h2><p>Demo data is generated in the browser and resets on reload. This link cannot restore the same record in another session.</p><button class="primary" data-action="session-home">View records in this session</button></section>`:tab==='log'?logView():tab==='lineage'?lineageView():tab==='team'?teamView():tab==='proposals'?proposalsView():verificationView();if($('#event-filter'))$('#event-filter').value=filter;}
function setTab(value){tab=value;unavailable=false;history.pushState(null,'',eventRoute(tab,demo.events[selected]?.hash));render();}
function selectEvent(index,value=tab){selected=index;verification=null;setTab(value);if(value==='lineage')$('#lineage-event')?.focus({preventScroll:true});if(value==='verify')$('#verify-event')?.focus({preventScroll:true});}
function readRoute(){if(!demo||location.hash==='#app')return;const route=parseRoute(location.hash,demo.events);tab=route.tab;unavailable=route.unavailable;if(route.index!==null)selected=route.index;verification=null;render();}
window.addEventListener('hashchange',readRoute);
window.addEventListener('popstate',readRoute);
function fields(){const type=$('#change-type').value;const state=demo.state;const candidate=['AAA','BBB','CCC'].filter(id=>!state.maintainers.includes(id));
  $('#change-fields').innerHTML=type==='recommend'?`<label>Recommended repository<select name="repository"><option value="nustar">NuSTAR · BioCode-Commons</option><option value="star">STAR · Original</option></select></label><label>Recommendation target<select name="targetType"><option value="version">Current commit · Pinned version</option><option value="repository">Whole repository · Future commits are not automatically endorsed</option></select></label>`:`<label>Candidate account<select name="candidate" ${candidate.length?'':'disabled'}>${candidate.map(id=>`<option value="${id}">${id}</option>`).join('')||'<option>No eligible candidates</option>'}</select></label>`;
  const authorized=type==='appoint'?actor==='admin':type==='recommend'?actor==='admin'||state.maintainers.includes(actor):state.maintainers.includes(actor);
  $('#submit-change').disabled=!authorized||(type!=='recommend'&&!candidate.length);$('#form-help').className='form-help'+(authorized?'':' error');$('#form-help').textContent=authorized?(type==='appoint'?'Administrators can issue invitations directly. Access starts only after candidate acceptance.':type==='recommend'?'Change the maintainer recommendation. The admin pick is managed separately.':'The proposal records your approval vote. A majority and candidate acceptance are required.'):`The current account, ${names[actor]}, cannot perform this action. Switch demo accounts first.`;
}
function openChange(type='recommend'){$('#change-type').value=type;$('#change-form').reset();$('#change-type').value=type;fields();$('#change-dialog').showModal();}
function download(value,name){const blob=new Blob([JSON.stringify(value,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
async function run(task){if(busy)return;busy=true;try{await task();}catch(error){toast(error.message,true);}finally{busy=false;render();}}
async function verifyCurrent(){let bundle=await demo.bundle(selected);if(sample==='tampered')bundle.events[selected].body.reason='Secretly rewritten reason: grant access to Mallory';if(sample==='truncated')bundle.events.pop();verification=await verifyBundle(bundle,demo.trust);}
document.addEventListener('click',event=>{const button=event.target.closest('button');if(!button||button.disabled||!demo)return;
  if(button.dataset.tab){setTab(button.dataset.tab);return;}
  if(button.dataset.event!==undefined){selectEvent(Number(button.dataset.event));return;}
  if(button.dataset.lineage!==undefined){selectEvent(Number(button.dataset.lineage),'lineage');return;}
  if(button.dataset.history!==undefined){selectEvent(Number(button.dataset.history),'log');return;}
  if(button.dataset.sample){sample=button.dataset.sample;verification=null;render();return;}
  if(button.dataset.vote){run(async()=>{await demo.vote(actor,button.dataset.vote);toast('Vote recorded publicly. The candidate must accept after the voting threshold is met.');});return;}
  if(button.dataset.accept){run(async()=>{await demo.accept(actor,button.dataset.accept);selected=demo.events.length-1;setTab(tab);toast('Candidate accepted. Team access is updated and publicly recorded.');});return;}
  const action=button.dataset.action;
  if(action==='show-lineage')setTab('lineage');
  else if(action==='session-home'){selected=demo.events.length-1;setTab('log');}
  else if(action==='copy-link')run(async()=>{await navigator.clipboard.writeText(new URL(eventRoute(tab,demo.events[selected].hash),location.href).href);toast('Session link copied. Reloading or opening another session cannot restore this demo record.');});
  else if(action==='open-change')openChange();
  else if(action==='open-invite')openChange('transfer');
  else if(action==='close-dialog')$('#change-dialog').close();
  else if(action==='verify-selected'){sample='original';verification=null;setTab('verify');run(verifyCurrent);}
  else if(action==='run-verify')run(verifyCurrent);
  else if(action==='download')run(async()=>{if(unavailable)throw Error('Select a record from this session first');download(await demo.bundle(selected),'crossomics-governance-evidence.json');toast('Public content, signatures, and inclusion proof downloaded.');});
  else if(action==='download-trust')download(demo.trust,'crossomics-demo-trust-roots.json');
  else if(action==='cross-tool')run(async()=>{await demo.recommend(actor,'star','version','Attempt to change another tool','cp_bwa');});
  else if(action==='reset')run(async()=>{demo=await createDemo();selected=demo.events.length-1;verification=null;sample='original';actor='AAA';setTab('log');toast('Demo reset. New local keys and a new log have been generated.');});
});
$('#actor').addEventListener('change',event=>{actor=event.target.value;render();toast(`Switched to: ${names[actor]} · ${role()}`);});
$('#change-type').addEventListener('change',fields);
document.addEventListener('change',event=>{if(event.target.id==='event-filter'){filter=event.target.value;render();}if(['verify-event','lineage-event'].includes(event.target.id)){selectEvent(Number(event.target.value));}});
$('#change-form').addEventListener('submit',event=>{event.preventDefault();const data=new FormData(event.target),type=data.get('action'),reason=String(data.get('reason')??'').trim();run(async()=>{
  if(type==='recommend')await demo.recommend(actor,data.get('repository'),data.get('targetType'),reason);
  else if(type==='appoint')await demo.appoint(actor,data.get('candidate'),reason);
  else await demo.propose(actor,type,data.get('candidate'),reason);
  $('#change-dialog').close();selected=demo.events.length-1;verification=null;setTab(type!=='recommend'?'proposals':'log');toast(type==='appoint'?'Administrator invitation published. Access starts after candidate acceptance.':type==='add'||type==='transfer'?'Proposal and proposer approval published. Awaiting votes from other members.':'Change appended to the demo log and a new checkpoint signed.');
});});
document.querySelector('.tabs').addEventListener('keydown',event=>{if(!['ArrowLeft','ArrowRight'].includes(event.key))return;event.preventDefault();const tabs=[...document.querySelectorAll('[data-tab]')];const i=tabs.indexOf(document.activeElement);const next=tabs[(i+(event.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length];next.focus();setTab(next.dataset.tab);});
try{if(!crypto.subtle)throw Error('Secure cryptography is unavailable in this browser context. Open the demo over HTTPS.');demo=await createDemo();selected=demo.events.length-1;readRoute();}catch(error){$('#app').innerHTML=`<div class="empty"><h2>Unable to initialize the demo</h2><p>${escape(error.message)}</p></div>`;}
